// BatchDeleteProducts validates the raw IDs before beginning the all-or-nothing transaction in 8.7.
func (c *ProductController) BatchDeleteProducts(ctx context.Context, req *productv1.BatchDeleteProductsRequest) (*productv1.BatchDeleteProductsResponse, error) {
	rawIDs := req.GetIds()
	if len(rawIDs) == 0 {
		return nil, connect.Errorf(connect.CodeInvalidArgument, "BatchDelete ID 集合不能为空")
	}
	distinctIDs := make([]int64, 0, len(rawIDs))
	seen := make(map[int64]struct{}, len(rawIDs))
	for _, id := range rawIDs {
		if _, duplicate := seen[id]; duplicate {
			continue
		}
		seen[id] = struct{}{}
		distinctIDs = append(distinctIDs, id)
	}
	if len(distinctIDs) > productBatchDeleteLimit {
		return nil, connect.Errorf(connect.CodeInvalidArgument, "BatchDelete ID 数量超过上限 %d", productBatchDeleteLimit)
	}
	var batchSnapshots []model.ProductItem
	if err := c.store.InTransaction(ctx, func(txRepo resource.Tx) error {
		models, err := c.repo.GetManyForUpdate(ctx, txRepo, distinctIDs, c.accessScope(ctx))
		if err != nil {
			return err
		}
		if len(models) != len(distinctIDs) {
			return resource.ErrNotFound
		}
		batchSnapshots = make([]model.ProductItem, len(models))
		for i, m := range models {
			batchSnapshots[i] = *m
		}
		if c.hooks.BeforeBatchDelete != nil {
			if err := c.hooks.BeforeBatchDelete(ctx, txRepo, models); err != nil {
				return err
			}
		}
		affected, err := c.repo.BatchDelete(ctx, txRepo, distinctIDs, c.accessScope(ctx))
		if err != nil {
			return err
		}
		if affected != int64(len(distinctIDs)) {
			return fmt.Errorf("Product: BatchDelete 影响行数 %d 与 distinct ID 数 %d 不一致", affected, len(distinctIDs))
		}
		if c.hooks.AfterBatchDelete != nil {
			if err := c.hooks.AfterBatchDelete(ctx, txRepo, models); err != nil {
				return err
			}
		}
		return nil
	}); err != nil {
		return nil, productRepositoryError(err)
	}
	if c.hooks.AfterCommitBatchDelete != nil {
		productRunAfterCommit("batch_delete", func() {
			c.hooks.AfterCommitBatchDelete(ctx, batchSnapshots)
		})
	}
	return &productv1.BatchDeleteProductsResponse{}, nil
}
